"use strict";(self.webpackChunkwiki_es=self.webpackChunkwiki_es||[]).push([["54991"],{52040(e){e.exports=JSON.parse('{"tag":{"label":"Placa portadora rob\xf3tica J401","permalink":"/es/tags/placa-portadora-robotica-j-401","allTagsPath":"/es/tags","count":1,"items":[{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Robotics_J40/es_reComputer_Robotics_Getting_Started","title":"Introducci\xf3n a reComputer Robotics","description":"La reComputer Robotics J401 es una placa portadora de IA de borde de alto rendimiento dise\xf1ada para aplicaciones avanzadas de rob\xf3tica. Es compatible con los m\xf3dulos NVIDIA Jetson Orin Nano y Orin NX en modo Super/MAXN, ofreciendo hasta 157 TOPS de potencia de c\xf3mputo de IA. La placa ofrece amplias opciones de conectividad, incluyendo Ethernet Gigabit dual, m\xfaltiples puertos USB 3.2, CAN, ranuras M.2 para m\xf3dulos 5G/Wi\u2011Fi/BT y compatibilidad opcional con c\xe1maras GMSL2. Con JetPack 6 preinstalado, garantiza un despliegue fluido para el desarrollo de rob\xf3tica. El dise\xf1o robusto admite un amplio rango de temperaturas de funcionamiento e incluye un disipador de calor con ventilador preinstalado. La configuraci\xf3n implica flashear el sistema operativo JetPack en un SSD NVMe usando un PC host Ubuntu compatible, seguido de la configuraci\xf3n del hardware y el uso de las interfaces. Se proporcionan especificaciones detalladas de hardware, dibujos mec\xe1nicos y recursos t\xe9cnicos para desarrolladores, junto con canales de soporte t\xe9cnico y de comunidad para resoluci\xf3n de problemas y discusi\xf3n.","permalink":"/es/recomputer_robotics_j401_getting_started"}],"unlisted":false}}')}}]);